        var m = e.data;
        if (!m || m.type !== "fs:stats-on") return;
        this.on = !!m.on;
        // Reset the whole accumulator, not just the flag: the gap between
        // switching off and back on is not a frame time.
        this.last = 0;
        this.acc = 0;
        this.frames = 0;
